4. const REACT_FAILED_PROP_TYPE = 'Failed prop';
5. const REACT_NO_KEYS = 'Each child in a list should have a unique "key" prop';
6. const REACT_DUPLICATE_KEYS = 'Encountered two children with the same key';
7. const REACT_PSUEDO_CLASS = 'The pseudo class ":first-child"';
8. const REACT_UNMATCHED_GET = 'Unmatched GET to';
9. const REACT_UNMOUNTED = 'React state update on an unmounted component';
10. const REACT_ERRORS = [
11.   REACT_FAILED_PROP_TYPE,
12.   REACT_NO_KEYS,
13.   REACT_DUPLICATE_KEYS,
14. ];
15. const REACT_SUPPRESSED_WARNINGS = [
16.   REACT_PSUEDO_CLASS,
17.   REACT_UNMATCHED_GET,
18.   REACT_UNMOUNTED,
19. ];
20. const REACT_ERRORS_REGEX = new RegExp(REACT_ERRORS.join('|'));
21. const REACT_SUPPRESSED_REGEX = new RegExp(REACT_SUPPRESSED_WARNINGS.join('|'));
22. 
23. const { error, warn } = console;
24. 
25. const didSuppressWarning = (message, ...rest) => {
26.   const { expectedWarnings } = window;
27.   if (REACT_SUPPRESSED_REGEX.test(message)) {
28.     return true;
29.   }
30.   if (expectedWarnings && Array.isArray(expectedWarnings)) {
31.     for (let i = 0; i < expectedWarnings.length; i += 1) {
32.       const warningsRegex = new RegExp(
33.         [REACT_FAILED_PROP_TYPE, ...expectedWarnings[i]].join('*.*'),
34.       );
35.       const consoleFormattedMessage = message.replace('%s', rest);
36.       if (warningsRegex.test(consoleFormattedMessage)) {
37.         window.expectedWarnings.splice(i, 1);
38.         return true;
39.       }
40.     }
41.   }
42.   return false;
43. };
44. 
45. // eslint-disable-next-line no-console
46. console.error = (message, ...rest) => {
47.   if (didSuppressWarning(message, ...rest)) return;
48. 
49.   if (REACT_ERRORS_REGEX.test(message)) {
50.     throw new Error(
51.       [
52.         chalk.red.bold(
53.           'Test failed because a React warning was detected. Please fix the following:',
54.         ),
55.         chalk.red(message),
56.       ].join('\n'),
57.     );
58.   }
59. 
60.   error(message, ...rest);
61. };
62. 
63. // eslint-disable-next-line no-console
64. console.warn = (message, ...rest) => {
65.   if (didSuppressWarning(message)) return;
66.   warn(message, ...rest);
